def second_largest(xs):
    if not xs:
        return None

    # Create a Min-Heap and store distinct elements from xs
    pq = PriorityQueue()
    for x in xs:
        if x not in pq.queue:
            pq.put(x)

    # We remove the first largest value (the current min)
    pq.get()

    # Now, get the second largest value, which will be an exception if only one unique value is present.
    try:
        return pq.queue.pop()
    except IndexError:
        return None

